      if (meta && (meta[3] === "D" || (meta[3] === "T" && meta[1] === "160000"))) stagedRemovals.push(staged[i + 1]);
    }
    if (stagedRemovals.length) git(["update-index", "--force-remove", "-z", "--stdin"], { input: `${stagedRemovals.join("\0")}\0` });
